from fastapi import APIRouter, Depends, HTTPException ,BackgroundTasks , Request
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy import select, func
from sqlalchemy.orm import joinedload
from app.db.deps import get_db
from app.models.user import User
from app.models.prediction import Prediction
from app.schemas.prediction import PredictionCreate, PredictionResponse
from app.services import ml_service
from app.api.deps import get_current_user
import time
from app.core.logging import get_logger

from app.services.audit_service import write_audit_log
from app.db.session import AsyncSessionLocal

from app.core.limiter import limiter
from app.core.config import settings

logger = get_logger("prediction")

router = APIRouter(prefix="/predictions", tags=["predictions"])
@router.post("/", response_model=PredictionResponse)
@limiter.limit(settings.RATE_LIMIT) # rate limit is set to 10/minutes

async def create_prediction(
    background_tasks: BackgroundTasks,
    request : Request ,
    prediction: PredictionCreate,
    current_user: User = Depends(get_current_user),
    db: AsyncSession = Depends(get_db)
):
    start_time = time.time()
    bound_logger = logger.bind(
        user_id = current_user.id,
        amount = prediction.amount,
        merchant = prediction.merchant
    )
    
    result = ml_service.predict(prediction.model_dump())


    bound_logger.info("prediction_made" ,
                 fraud_score = result["fraud_score"],
                 is_fraud=result["is_fraud"],
                 model_version=result["model_version"],
                 latency_ms = round((time.time() - start_time) * 1000, 2)
                )
    db_prediction = Prediction(
        user_id=current_user.id,
        amount=prediction.amount,
        merchant=prediction.merchant,
        card_type=prediction.card_type,
        fraud_score=result["fraud_score"],
        is_fraud=result["is_fraud"],
        model_version=result["model_version"]
    )
    db.add(db_prediction)
    await db.commit()
    await db.refresh(db_prediction)

    background_tasks.add_task(
        write_audit_log,
        prediction_id=db_prediction.id,
        user_id=current_user.id,
        ip_address=request.client.host,
        endpoint="/predictions/",
        status_code=200,
        latency_ms=round((time.time() - start_time) * 1000, 2),
        db=AsyncSessionLocal(),
    )
    return db_prediction

@router.get("/stats")
async def get_stats(current_user: User = Depends(get_current_user), db: AsyncSession = Depends(get_db)):
    result = await db.execute(
        select(
            func.count().label("total"),
            func.avg(Prediction.fraud_score).label("avg_score"),
            func.count().filter(Prediction.is_fraud == True).label("total_flagged")
        ).where(Prediction.user_id == current_user.id)
    )
    row = result.one()
    return {
        "total_predictions": row.total,
        "avg_fraud_score": row.avg_score,
        "total_flagged": row.total_flagged
    }

@router.get("/with-user")
async def get_with_user(db: AsyncSession = Depends(get_db)):
    result = await db.execute(
        select(Prediction)
        .join(User)
        .options(joinedload(Prediction.owner))
        .limit(10)
    )
    predictions = result.scalars().all()
    return [
        {
            "id": p.id,
            "merchant": p.merchant,
            "fraud_score": p.fraud_score,
            "is_fraud": p.is_fraud,
            "user_email": p.owner.email
        }
        for p in predictions
    ]

@router.get("/", response_model=list[PredictionResponse])
async def get_predictions(
    current_user: User = Depends(get_current_user),
    skip: int = 0,
    limit: int = 20,
    db: AsyncSession = Depends(get_db)
):
    query = select(Prediction).where(Prediction.user_id == current_user.id).offset(skip).limit(limit)
    result = await db.execute(query)
    rows = result.scalars().all()
    return rows
   